// Render check for the isometric remastered games (slimefarm, minecrawler):
//   node studio/griddly-demo/tools/remaster/iso_check.mjs <game_id> [--png outDir]
//
// For every level it renders, in the WASM engine:
//   * the global `Isometric` observer (createGame("Isometric", "IsoFollow") + observeImage)
//   * the player's `IsoFollow` observer (observePlayerImage)
//   * the global `Sprite2D` observer (separate game)
// and asserts each image is > 30% lit (pixel sum > 30). Images generated by the remaster tools
// (resources/images/remastered/*.png) are written into the engine's virtual FS first, because the
// prebuilt griddlyjs.data only contains the images that existed when the WASM was packaged.
// With --png the renders are also written as PNG files for eyeballing. Exits non-zero on failure.
import fs from "fs";
import path from "path";
import zlib from "zlib";
import { fileURLToPath } from "url";

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, "../../../..");
const { createGriddly } = await import(path.join(root, "studio/griddly-demo/packages/ts/griddly-wasm/dist/index.js"));

const id = process.argv[2];
const pngDir = process.argv.includes("--png") ? process.argv[process.argv.indexOf("--png") + 1] : null;
const gdy = fs.readFileSync(path.join(root, "resources/games/Single-Player/Remastered", `${id}.yaml`), "utf8");

const g = await createGriddly({ moduleOverrides: { print() {}, printErr() {} } });
export function syncImages(g) {
  const FS = g.module.FS;
  let n = 0;
  for (const sub of ["remastered", "memes"]) {  // memes/: Phase 4 memekit art
    const dir = path.join(root, "resources/images", sub);
    if (!fs.existsSync(dir)) continue;
    if (!FS.analyzePath(`/resources/images/${sub}`).exists) FS.mkdir(`/resources/images/${sub}`);
    for (const f of fs.readdirSync(dir)) {
      if (!f.endsWith(".png")) continue;
      FS.writeFile(`/resources/images/${sub}/${f}`, fs.readFileSync(path.join(dir, f)));
      n++;
    }
  }
  return n;
}
syncImages(g);

function png(file, { pixels, width, height }) {
  const raw = Buffer.alloc((width * 4 + 1) * height);
  for (let y = 0; y < height; y++) {
    raw[y * (width * 4 + 1)] = 0;
    Buffer.from(pixels.buffer, pixels.byteOffset + y * width * 4, width * 4).copy(raw, y * (width * 4 + 1) + 1);
  }
  const crcTable = Array.from({ length: 256 }, (_, n) => {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    return c >>> 0;
  });
  const crc = (b) => {
    let c = 0xffffffff;
    for (const x of b) c = crcTable[(c ^ x) & 255] ^ (c >>> 8);
    return (c ^ 0xffffffff) >>> 0;
  };
  const chunk = (t, d) => {
    const len = Buffer.alloc(4);
    len.writeUInt32BE(d.length);
    const td = Buffer.concat([Buffer.from(t), d]);
    const c = Buffer.alloc(4);
    c.writeUInt32BE(crc(td));
    return Buffer.concat([len, td, c]);
  };
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0);
  ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8;
  ihdr[9] = 6;
  fs.writeFileSync(file, Buffer.concat([Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]), chunk("IHDR", ihdr),
    chunk("IDAT", zlib.deflateSync(raw)), chunk("IEND", Buffer.alloc(0))]));
}

const lit = ({ pixels, width, height }) => {
  let n = 0;
  for (let i = 0; i < pixels.length; i += 4) if (pixels[i] + pixels[i + 1] + pixels[i + 2] > 30) n++;
  return n / (width * height);
};

let failed = false;
const views = [["Isometric", "IsoFollow"], ["Sprite2D", "FollowCam"]].filter(([o]) => o !== "Isometric" || /\n    Isometric:/.test(gdy));
const results = {};
for (const [globalObs, playerObs] of views) {
  // a fresh game per level: the global observer renders black after loadLevel() switches size
  g.loadGDYString(gdy);
  g.createGame(globalObs, playerObs);
  const n = g.getLevelCount();
  for (let l = 0; l < n; l++) {
    g.loadGDYString(gdy);
    g.createGame(globalObs, playerObs);
    g.loadLevel(l);
    g.seed(1);
    g.reset();
    // copy each frame at once: the pixels are a view into WASM memory, which the next render may grow (detaching it)
    const snap = (im) => ({ width: im.width, height: im.height, pixels: new Uint8Array(im.pixels) });
    const globalIm = snap(await g.observeImage());
    const playerIm = snap(await g.observePlayerImage(0));
    for (const [name, im] of [[globalObs, globalIm], [playerObs, playerIm]]) {
      const f = lit(im);
      const ok = f > 0.3;
      if (!ok) failed = true;
      (results[l] ??= []).push(`${name} ${im.width}x${im.height} lit ${(100 * f).toFixed(0)}%${ok ? "" : " FAIL"}`);
      if (pngDir) {
        fs.mkdirSync(pngDir, { recursive: true });
        png(path.join(pngDir, `${id}-L${l}-${name}.png`), im);
      }
    }
  }
}
for (const [l, r] of Object.entries(results)) console.log(`  ${id} L${l}: ${r.join(" | ")}`);
process.exit(failed ? 1 : 0);
